         alt: "A mountain road with a car driving through a dark forest at dusk",
         name: "Night Drive",
         details: "JPEG · 4.8 MB · Added 2 days ago"
       };

       function Button({ className = "", type = "button", label, attrs = "" }) {
         return `<button type="${type}" class="button ${className}" ${attrs}>${label}</button>`;
       }

       function ConfirmDeleteDialog() {
         return `
           <dialog id="confirm-delete-dialog" aria-labelledby="confirm-delete-title" aria-describedby="confirm-delete-body">
             <form method="dialog" class="dialog-shell">
               <div class="dialog-header">
                 <h2 id="confirm-delete-title" class="dialog-title">Delete this image from your library?</h2>
                 <p id="confirm-delete-body" class="dialog-body">
                   This image will be removed from your library and won't be easy to recover.
                 </p>
               </div>
               <div class="dialog-actions">
                 ${Button({ className: "cancel", label: "Cancel", attrs: 'value="cancel" autofocus' })}
                 ${Button({ className: "destructive", label: "Delete image", attrs: 'value="delete"' })}
               </div>
             </form>
           </dialog>
         `;
       }

       function ImagePreviewPage() {
         return `
           <main id="main" class="page" tabindex="-1">
             <section class="hero" aria-labelledby="page-title">
               <p class="eyebrow">Image preview</p>
               <h1 id="page-title">Review before removing it</h1>
               <p class="subtitle">
                 Preview the selected image and choose whether to keep it in your library or delete it permanently.
               </p>
             </section>

             <section class="preview-card" aria-labelledby="image-title">
               <div class="image-frame">
                 <img src="${image.src}" alt="${image.alt}" />
               </div>
               <div class="meta">
                 <div class="file-info">
                   <strong id="image-title">${image.name}</strong>
                   <span>${image.details}</span>
                 </div>
                 <div class="actions">
                   ${Button({ className: "trigger", label: "Delete image", attrs: 'data-open-delete-dialog aria-haspopup="dialog" aria-controls="confirm-delete-dialog"' })}
                 </div>
               </div>
             </section>
           </main>
         `;
       }

       function App() {
         return ImagePreviewPage() + ConfirmDeleteDialog();
       }

       document.getElementById("app").innerHTML = App();

       const dialog = document.getElementById("confirm-delete-dialog");
       const trigger = document.querySelector(".trigger[data-open-delete-dialog]");

       trigger.addEventListener("click", () => {
         dialog.showModal();
       });
     </script>
   </body>
 </html>

